});

const http = require("https");

const options = {
  "method": "GET",
  "hostname": "example.myintranetapps.com",
  "port": null,
  "path": "/api/accounting_transactions?start=SOME_STRING_VALUE&end=SOME_STRING_VALUE&page=SOME_INTEGER_VALUE&itemsPerPage=SOME_INTEGER_VALUE",
  "headers": {
    "Authorization": "Basic REPLACE_BASIC_AUTH"
  }
};

const req = http.request(options, function (res) {
  const chunks = [];

  res.on("data", function (chunk) {
    chunks.push(chunk);
  });

  res.on("end", function () {
    const body = Buffer.concat(chunks);
    console.log(body.toString());
  });
});

req.end();

